package com.shelter.api.medical;
import com.shelter.api.animal.Animal; import jakarta.persistence.*; import java.time.LocalDate; import java.time.OffsetDateTime; import java.util.UUID;
@Entity @Table(name="vaccinations") public class Vaccination {
 @Id private UUID id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="animal_id",nullable=false) private Animal animal;
 @Column(name="vaccine_name",nullable=false,length=160) private String vaccineName; private String vaccineType; @Column(nullable=false) private LocalDate administeredDate; private LocalDate nextDueDate; private String batchNumber; private String veterinarian; @Column(columnDefinition="TEXT") private String notes; private String createdBy; private OffsetDateTime createdAt;
 @PrePersist void create(){if(id==null)id=UUID.randomUUID();if(createdAt==null)createdAt=OffsetDateTime.now();}
 public UUID getId(){return id;} public Animal getAnimal(){return animal;} public void setAnimal(Animal v){animal=v;} public String getVaccineName(){return vaccineName;} public void setVaccineName(String v){vaccineName=v;} public String getVaccineType(){return vaccineType;} public void setVaccineType(String v){vaccineType=v;} public LocalDate getAdministeredDate(){return administeredDate;} public void setAdministeredDate(LocalDate v){administeredDate=v;} public LocalDate getNextDueDate(){return nextDueDate;} public void setNextDueDate(LocalDate v){nextDueDate=v;} public String getBatchNumber(){return batchNumber;} public void setBatchNumber(String v){batchNumber=v;} public String getVeterinarian(){return veterinarian;} public void setVeterinarian(String v){veterinarian=v;} public String getNotes(){return notes;} public void setNotes(String v){notes=v;} public String getCreatedBy(){return createdBy;} public void setCreatedBy(String v){createdBy=v;} public OffsetDateTime getCreatedAt(){return createdAt;}
}